// Supabase Edge Function `seal-worker`: runs ONE seal step per invocation
// (docs/supabase-native-architecture.md). `dist/` is generated by
// `pnpm --filter api build:edge`; see apps/api/scripts/build-edge.mjs.
//
// Called by pg_cron (via pg_net) every minute as a backstop, and by itself:
// when a step leaves more to do, the worker calls its own URL after
// answering, so the next step starts at once on a new invocation with its
// own CPU budget. A step that fails backs off in the job row and does not
// re-kick. Every call must carry `X-Cron-Secret: $CRON_SECRET`.
import { ASSET_ROOT, installAssetFs } from '../_shared/asset-fs.ts';
import { secretMatches } from '../_shared/secret.ts';
import assets from './dist/assets.mjs';

installAssetFs(assets as Record<string, string>);
(globalThis as { __SEALD_ASSET_DIR?: string }).__SEALD_ASSET_DIR = ASSET_ROOT;

const { createSealWorker } = await import('./dist/edge.mjs');

const cronSecret = Deno.env.get('CRON_SECRET') ?? '';
const selfUrl =
  Deno.env.get('SEAL_WORKER_URL') ??
  `${(Deno.env.get('SUPABASE_URL') ?? '').replace(/\/$/, '')}/functions/v1/seal-worker`;

type Worker = { runOneStep(): Promise<{ kind: string }> };
let worker: Worker | null = null;
// The runtime counts CPU per worker, and may route two requests (a cron
// tick and a self-kick) to the same one. Two steps at once could push it
// past the hard limit mid-step, so a worker runs one step at a time.
let busy = false;

Deno.serve(async (req: Request) => {
  if (req.method !== 'POST') return new Response('method_not_allowed', { status: 405 });
  if (
    cronSecret.length < 32 ||
    !(await secretMatches(req.headers.get('x-cron-secret'), cronSecret))
  ) {
    return new Response('invalid_cron_secret', { status: 401 });
  }
  if (busy) return Response.json({ kind: 'busy' });
  busy = true;
  let outcome: { kind: string };
  try {
    // Built on the first request, not at module load, so a misconfiguration
    // answers 500 with the error in the function logs instead of failing boot.
    worker ??= (createSealWorker as () => Worker)();
    outcome = await worker.runOneStep();
  } finally {
    busy = false;
  }
  if (outcome.kind === 'yielded' || outcome.kind === 'finished') {
    // More may be queued: hand the next step to a fresh invocation.
    EdgeRuntime.waitUntil(
      fetch(selfUrl, { method: 'POST', headers: { 'x-cron-secret': cronSecret } })
        .then((res) => res.body?.cancel())
        .catch((err: unknown) => console.error('seal-worker self-kick failed', err)),
    );
  }
  return Response.json(outcome);
});
